#!/usr/bin/env bash
# linux-step-1-1.sh: step 1.1 of the spectroscope Local Setup page, Linux.
# Generated by docs/local-setup/build_local_setup.py for docs/local-setup/index.html on 2026-10-12.
# The lines below are the copy blocks of this step, run in order. The page shows
# the step's other blocks (alternatives, lines you run later by hand) separately.
# Read the lines before you run this.
set -euo pipefail

curl -fsSL https://apt.spectroscope.dev/spectroscope.asc | sudo gpg --dearmor -o /usr/share/keyrings/spectroscope.gpg
echo "deb [signed-by=/usr/share/keyrings/spectroscope.gpg] https://apt.spectroscope.dev stable main" | sudo tee /etc/apt/sources.list.d/spectroscope.list
sudo apt update && sudo apt install spectroscope
